std::vector<std::vector<long long> > connectedComponents(long long n, std::vector<std::vector<long long> > edges) {
    std::vector<std::vector<long long> > adjacency((std::size_t)n);
    for (std::size_t i = 0; i < edges.size(); ++i) {
        long long a = edges[i][0];
        long long b = edges[i][1];
        adjacency[(std::size_t)a].push_back(b);
        adjacency[(std::size_t)b].push_back(a);
    }

    std::vector<bool> seen((std::size_t)n, false);
    std::vector<std::vector<long long> > components;
    for (long long start = 0; start < n; ++start) {
        if (seen[(std::size_t)start]) continue;
        seen[(std::size_t)start] = true;
        std::vector<long long> stack;
        std::vector<long long> component;
        stack.push_back(start);
        while (!stack.empty()) {
            long long node = stack.back();
            stack.pop_back();
            component.push_back(node);
            const std::vector<long long>& neighbours = adjacency[(std::size_t)node];
            for (std::size_t k = 0; k < neighbours.size(); ++k) {
                long long next = neighbours[k];
                if (!seen[(std::size_t)next]) {
                    seen[(std::size_t)next] = true;
                    stack.push_back(next);
                }
            }
        }
        std::sort(component.begin(), component.end());
        components.push_back(component);
    }
    return components;
}

