function connectedComponents(n, edges) {
  const adjacency = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    adjacency[a].push(b);
    adjacency[b].push(a);
  }

  const seen = new Array(n).fill(false);
  const components = [];
  for (let start = 0; start < n; start += 1) {
    if (seen[start]) continue;
    seen[start] = true;
    const stack = [start];
    const component = [];
    while (stack.length > 0) {
      const node = stack.pop();
      component.push(node);
      for (const neighbour of adjacency[node]) {
        if (!seen[neighbour]) {
          seen[neighbour] = true;
          stack.push(neighbour);
        }
      }
    }
    components.push(component.sort((x, y) => x - y));
  }
  return components;
}
